// Spawns a particle effect together with its layers (flash, embers, smoke, shockwave … — see particle_layers.js,
// generated by tools/gen_particles.py). Every layer gets the same colour as the base effect.
// v1.54 — lighter, the effects untouched:
//   • nobody within 64 blocks to see it → not spawned at all;
//   • the same effect at the same spot twice in one tick (loops that overlap) → spawned once;
//   • per tick, server-wide: at most 48 layer emitters and 140 emitters in all (a huge fight stays smooth).

import { world, system, MolangVariableMap } from "@minecraft/server";
import { LAYERS } from "./particle_layers.js";

const LAYER_BUDGET = 48;
const TOTAL_BUDGET = 140;
const VIEW2 = 64 * 64;
let tick = -1;
let used = 0;
let total = 0;
const seen = new Set();
let viewers = [];

function refresh() {
  if (system.currentTick === tick) return;
  tick = system.currentTick;
  used = 0;
  total = 0;
  seen.clear();
  viewers = [];
  try {
    for (const p of world.getAllPlayers()) viewers.push({ d: p.dimension.id, x: p.location.x, y: p.location.y, z: p.location.z });
  } catch {
    /* ignore */
  }
}

function watched(dim, loc) {
  for (const v of viewers) {
    if (v.d !== dim.id) continue;
    const dx = v.x - loc.x;
    const dy = v.y - loc.y;
    const dz = v.z - loc.z;
    if (dx * dx + dy * dy + dz * dz < VIEW2) return true;
  }
  return false;
}

export function spawnLayered(dim, id, loc, color) {
  refresh();
  if (!loc || !watched(dim, loc)) return;
  const key = `${id}|${Math.round(loc.x * 2)}|${Math.round(loc.y * 2)}|${Math.round(loc.z * 2)}`;
  if (seen.has(key)) return;
  seen.add(key);
  if (total >= TOTAL_BUDGET) return;
  let vars;
  if (color) {
    vars = new MolangVariableMap();
    vars.setColorRGB("variable.color", { red: color[0], green: color[1], blue: color[2] });
  }
  const one = (pid) => {
    total++;
    try {
      if (vars) dim.spawnParticle(pid, loc, vars);
      else dim.spawnParticle(pid, loc);
    } catch {
      /* unknown particle or unloaded chunk */
    }
  };
  one(id);
  const layers = LAYERS[id];
  if (!layers) return;
  for (const pid of layers) {
    if (used >= LAYER_BUDGET || total >= TOTAL_BUDGET) return;
    used++;
    one(pid);
  }
}
